            break;
        }
        case PhysicsShape::Type::BOX:
        case PhysicsShape::Type::POLYGON:
        {
            int count = cpPolyShapeGetCount(cpShape);
            if (count <= 0) break;
            Vec2* verts = new (std::nothrow) Vec2[count];
            if (verts == nullptr) break;
