        case PhysicsShape::Type::EDGESEGMENT:
        case PhysicsShape::Type::EDGEBOX:
        case PhysicsShape::Type::EDGEPOLYGON:
        case PhysicsShape::Type::EDGECHAIN:
        {
            float radius = PhysicsHelper::cpfloat2float(cpSegmentShapeGetRadius(cpShape));
            Vec2 a = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpSegmentShapeGetA(cpShape)));
            Vec2 b = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpSegmentShapeGetB(cpShape)));
            drawSegmentShape(a, b, radius, outlineColor);
