 ****************************************************************************/

#include "physics/CCPhysicsDebugDraw.h"
#if CC_USE_PHYSICS

#include <cmath>
#include "2d/CCDrawNode.h"
#include "physics/CCPhysicsBody.h"
#include "physics/CCPhysicsShape.h"
#include "physics/CCPhysicsJoint.h"
#include "physics/CCPhysicsWorld.h"
#include "physics/CCPhysicsHelper.h"

NS_CC_BEGIN

namespace
{
    const int CIRCLE_SEGMENTS = 32;
    const float CONTACT_POINT_SIZE = 4.0f;
    const float JOINT_POINT_SIZE = 3.0f;
    const float ARROW_HEAD_LENGTH = 6.0f;
}

PhysicsDebugDraw::PhysicsDebugDraw()
: _drawNode(nullptr)
, _initialized(false)
{
    _config.drawShapes = true;
    _config.drawJoints = true;
    _config.drawContacts = false;
    _config.drawBoundingBoxes = false;
    _config.drawCentersOfMass = false;
    _config.drawVelocities = false;
    _config.drawSleepState = false;
    _config.shapeColor = Color4F(0.0f, 1.0f, 0.0f, 0.5f);
    _config.jointColor = Color4F(0.0f, 0.0f, 1.0f, 0.8f);
    _config.contactColor = Color4F(1.0f, 0.0f, 0.0f, 1.0f);
    _config.bbColor = Color4F(1.0f, 1.0f, 0.0f, 0.3f);
    _config.lineWidth = 1.0f;
}

PhysicsDebugDraw::~PhysicsDebugDraw()
{
}

bool PhysicsDebugDraw::init(DrawNode* drawNode)
{
    if (drawNode == nullptr)
    {
        return false;
    }

    _drawNode = drawNode;
    _initialized = true;
    return true;
}

void PhysicsDebugDraw::setConfig(const PhysicsDebugDrawConfig& config)
{
    _config = config;
}

PhysicsDebugDrawConfig PhysicsDebugDraw::getConfig() const
{
    return _config;
}

void PhysicsDebugDraw::beginDraw()
{
    // DrawNode batches its primitives and renders them through the scene
    // graph, so there is no explicit render state to push here. This call
    // only validates that the drawer is ready to accept primitives.
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }
}

void PhysicsDebugDraw::endDraw()
{
    // Nothing to flush: DrawNode renders the buffered primitives itself.
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }
}

void PhysicsDebugDraw::clear()
{
    if (_drawNode != nullptr)
    {
        _drawNode->clear();
    }
}

void PhysicsDebugDraw::drawWorld(PhysicsWorld* world)
{
    if (!_initialized || _drawNode == nullptr || world == nullptr)
    {
        return;
    }

    beginDraw();

    // A world redraw always starts from an empty buffer, otherwise the
    // primitives of the previous frames would accumulate.
    clear();

    for (auto body : world->getAllBodies())
    {
        drawBody(body);
    }

    if (_config.drawJoints)
    {
        for (auto joint : world->_joints)
        {
            drawJoint(joint);
        }
    }

    endDraw();
}

void PhysicsDebugDraw::drawBody(PhysicsBody* body)
{
    if (!_initialized || _drawNode == nullptr || body == nullptr)
    {
        return;
    }

    if (_config.drawShapes)
    {
        for (auto shape : body->getShapes())
        {
            drawShape(shape);
        }
    }

    if (_config.drawBoundingBoxes)
    {
        for (auto shape : body->getShapes())
        {
            for (auto cpShape : shape->_cpShapes)
            {
                drawBoundingBox(PhysicsHelper::cpbb2rect(cpShapeGetBB(cpShape)), _config.bbColor);
            }
        }
    }

    Vec2 position = body->getPosition();

    if (_config.drawVelocities && body->isDynamic())
    {
        drawVelocityVector(position, body->getVelocity(), Color4F(1.0f, 0.5f, 0.0f, 1.0f));
    }

    if (_config.drawCentersOfMass)
    {
        cpBody* cpBody = body->getCPBody();
        Vec2 center = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpBodyGetCenterOfGravity(cpBody)));
        drawCenterOfMass(center, 4.0f, Color4F::WHITE);
    }

    if (_config.drawSleepState)
    {
        drawSleepIndicator(position, body->isResting(), _config.shapeColor);
    }
}

void PhysicsDebugDraw::drawShape(PhysicsShape* shape)
{
    if (!_initialized || _drawNode == nullptr || shape == nullptr)
    {
        return;
    }

    Color4F fillColor = getShapeColor(shape);
    Color4F outlineColor(fillColor.r, fillColor.g, fillColor.b, 1.0f);

    for (auto cpShape : shape->_cpShapes)
    {
        cpBody* cpBody = cpShapeGetBody(cpShape);

        switch (shape->getType())
        {
        case PhysicsShape::Type::CIRCLE:
        {
            float radius = PhysicsHelper::cpfloat2float(cpCircleShapeGetRadius(cpShape));
            Vec2 center = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpCircleShapeGetOffset(cpShape)));
            float angle = PhysicsHelper::cpfloat2float(cpBodyGetAngle(cpBody));
            drawCircleShape(center, radius, angle, fillColor, outlineColor);
            break;
        }
        case PhysicsShape::Type::BOX:
        case PhysicsShape::Type::POLYGON:
        {
            int count = cpPolyShapeGetCount(cpShape);
            if (count <= 0)
            {
                break;
            }
            Vec2* verts = new (std::nothrow) Vec2[count];
            if (verts == nullptr)
            {
                break;
            }
            for (int i = 0; i < count; ++i)
            {
                verts[i] = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpPolyShapeGetVert(cpShape, i)));
            }
            drawPolygonShape(verts, count, fillColor, outlineColor);
            delete[] verts;
            break;
        }
        case PhysicsShape::Type::EDGESEGMENT:
        case PhysicsShape::Type::EDGEBOX:
        case PhysicsShape::Type::EDGEPOLYGON:
        case PhysicsShape::Type::EDGECHAIN:
        {
            // All edge shapes are stored as chipmunk segment shapes (an edge
            // chain holds one segment per link).
            float radius = PhysicsHelper::cpfloat2float(cpSegmentShapeGetRadius(cpShape));
            Vec2 a = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpSegmentShapeGetA(cpShape)));
            Vec2 b = PhysicsHelper::cpv2point(cpBodyLocalToWorld(cpBody, cpSegmentShapeGetB(cpShape)));
            drawSegmentShape(a, b, radius, outlineColor);
            break;
        }
        default:
            break;
        }
    }
}

void PhysicsDebugDraw::drawJoint(PhysicsJoint* joint)
{
    if (!_initialized || _drawNode == nullptr || joint == nullptr)
    {
        return;
    }

    const Color4F& color = _config.jointColor;

    for (auto constraint : joint->_cpConstraints)
    {
        cpBody* bodyA = cpConstraintGetBodyA(constraint);
        cpBody* bodyB = cpConstraintGetBodyB(constraint);

        if (cpConstraintIsPinJoint(constraint))
        {
            cpPinJoint* pinJoint = (cpPinJoint*)constraint;
            Vec2 anchorA = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyA, cpPinJointGetAnchorA(pinJoint)));
            Vec2 anchorB = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyB, cpPinJointGetAnchorB(pinJoint)));
            drawPinJoint(anchorA, anchorB, color);
        }
        else if (cpConstraintIsSlideJoint(constraint))
        {
            cpSlideJoint* slideJoint = (cpSlideJoint*)constraint;
            Vec2 anchorA = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyA, cpSlideJointGetAnchorA(slideJoint)));
            Vec2 anchorB = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyB, cpSlideJointGetAnchorB(slideJoint)));
            float minDist = PhysicsHelper::cpfloat2float(cpSlideJointGetMin(slideJoint));
            float maxDist = PhysicsHelper::cpfloat2float(cpSlideJointGetMax(slideJoint));
            drawSlideJoint(anchorA, anchorB, minDist, maxDist, color);
        }
        else if (cpConstraintIsDampedSpring(constraint))
        {
            cpDampedSpring* springJoint = (cpDampedSpring*)constraint;
            Vec2 anchorA = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyA, cpDampedSpringGetAnchorA(springJoint)));
            Vec2 anchorB = PhysicsHelper::cpv2point(cpBodyLocalToWorld(bodyB, cpDampedSpringGetAnchorB(springJoint)));
            float restLength = PhysicsHelper::cpfloat2float(cpDampedSpringGetRestLength(springJoint));
            drawSpringJoint(anchorA, anchorB, restLength, color);
        }
        else
        {
            // Constraints without a dedicated visualization (groove, gear,
            // rotary, motor, ...) are drawn as a link between body centers.
            Vec2 posA = PhysicsHelper::cpv2point(cpBodyGetPosition(bodyA));
            Vec2 posB = PhysicsHelper::cpv2point(cpBodyGetPosition(bodyB));
            _drawNode->drawSegment(posA, posB, _config.lineWidth, color);
        }
    }
}

void PhysicsDebugDraw::drawCircleShape(const Vec2& center, float radius, float angle,
                                       const Color4F& fillColor, const Color4F& outlineColor)
{
    if (!_initialized || _drawNode == nullptr || radius <= 0.0f)
    {
        return;
    }

    Vec2 verts[CIRCLE_SEGMENTS];
    for (int i = 0; i < CIRCLE_SEGMENTS; ++i)
    {
        float theta = angle + 2.0f * (float)M_PI * (float)i / (float)CIRCLE_SEGMENTS;
        verts[i].set(center.x + radius * cosf(theta), center.y + radius * sinf(theta));
    }
    _drawNode->drawPolygon(verts, CIRCLE_SEGMENTS, fillColor, _config.lineWidth, outlineColor);

    // A radius line indicates the body rotation.
    _drawNode->drawLine(center, center + Vec2(radius * cosf(angle), radius * sinf(angle)), outlineColor);
}

void PhysicsDebugDraw::drawPolygonShape(const Vec2* verts, int count,
                                        const Color4F& fillColor, const Color4F& outlineColor)
{
    if (!_initialized || _drawNode == nullptr || verts == nullptr || count < 3)
    {
        return;
    }

    _drawNode->drawPolygon(verts, count, fillColor, _config.lineWidth, outlineColor);
}

void PhysicsDebugDraw::drawSegmentShape(const Vec2& a, const Vec2& b, float radius,
                                        const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    float thickness = radius > 0.0f ? radius : _config.lineWidth;
    _drawNode->drawSegment(a, b, thickness, color);
}

void PhysicsDebugDraw::drawBoundingBox(const Rect& bb, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    Vec2 origin(bb.getMinX(), bb.getMinY());
    Vec2 destination(bb.getMaxX(), bb.getMaxY());
    _drawNode->drawRect(origin, destination, color);
}

void PhysicsDebugDraw::drawContactPoint(const Vec2& point, const Vec2& normal, float depth,
                                        const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawPoint(point, CONTACT_POINT_SIZE, color);

    // Visualize the contact normal scaled by the penetration depth.
    float length = fabsf(depth);
    if (length <= 0.0f)
    {
        length = 8.0f;
    }
    _drawNode->drawSegment(point, point + normal * length, _config.lineWidth, color);
}

void PhysicsDebugDraw::drawVelocityVector(const Vec2& pos, const Vec2& vel, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr || vel.isZero())
    {
        return;
    }

    Vec2 end = pos + vel;
    _drawNode->drawSegment(pos, end, _config.lineWidth, color);

    // Arrow head at the tip of the vector.
    Vec2 dir = vel.getNormalized();
    Vec2 perp(-dir.y, dir.x);
    Vec2 base = end - dir * ARROW_HEAD_LENGTH;
    _drawNode->drawLine(end, base + perp * (ARROW_HEAD_LENGTH * 0.5f), color);
    _drawNode->drawLine(end, base - perp * (ARROW_HEAD_LENGTH * 0.5f), color);
}

void PhysicsDebugDraw::drawCenterOfMass(const Vec2& pos, float radius, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr || radius <= 0.0f)
    {
        return;
    }

    _drawNode->drawLine(pos - Vec2(radius, 0.0f), pos + Vec2(radius, 0.0f), color);
    _drawNode->drawLine(pos - Vec2(0.0f, radius), pos + Vec2(0.0f, radius), color);
    _drawNode->drawPoint(pos, 2.0f, color);
}

void PhysicsDebugDraw::drawSleepIndicator(const Vec2& pos, bool sleeping, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    // A resting body gets a gray, fully opaque marker; an awake body gets a
    // dimmer one tinted with the shape color.
    Color4F indicatorColor = color;
    if (sleeping)
    {
        indicatorColor.r = 0.5f;
        indicatorColor.g = 0.5f;
        indicatorColor.b = 0.5f;
        indicatorColor.a = 1.0f;
    }
    else
    {
        indicatorColor.a *= 0.4f;
    }

    _drawNode->drawCircle(pos + Vec2(0.0f, 12.0f), 4.0f, 0.0f, 12, false, indicatorColor);
}

void PhysicsDebugDraw::drawPinJoint(const Vec2& anchorA, const Vec2& anchorB, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawSegment(anchorA, anchorB, _config.lineWidth, color);
    _drawNode->drawPoint(anchorA, JOINT_POINT_SIZE, color);
    _drawNode->drawPoint(anchorB, JOINT_POINT_SIZE, color);
}

void PhysicsDebugDraw::drawSpringJoint(const Vec2& anchorA, const Vec2& anchorB,
                                       float restLength, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    Vec2 delta = anchorB - anchorA;
    float length = delta.getLength();
    if (length <= 0.0f)
    {
        _drawNode->drawPoint(anchorA, JOINT_POINT_SIZE, color);
        return;
    }

    Vec2 dir = delta / length;
    Vec2 perp(-dir.y, dir.x);

    // The coil amplitude follows the rest length, clamped for readability.
    float amplitude = 6.0f;
    if (restLength > 0.0f && restLength * 0.15f < amplitude)
    {
        amplitude = restLength * 0.15f;
    }

    const int coils = 8;
    Vec2 previous = anchorA;
    for (int i = 1; i < coils; ++i)
    {
        float t = (float)i / (float)coils;
        float offset = (i % 2 == 0) ? -amplitude : amplitude;
        Vec2 point = anchorA + delta * t + perp * offset;
        _drawNode->drawLine(previous, point, color);
        previous = point;
    }
    _drawNode->drawLine(previous, anchorB, color);

    _drawNode->drawPoint(anchorA, JOINT_POINT_SIZE, color);
    _drawNode->drawPoint(anchorB, JOINT_POINT_SIZE, color);
}

void PhysicsDebugDraw::drawSlideJoint(const Vec2& anchorA, const Vec2& anchorB,
                                      float minDist, float maxDist, const Color4F& color)
{
    if (!_initialized || _drawNode == nullptr)
    {
        return;
    }

    _drawNode->drawSegment(anchorA, anchorB, _config.lineWidth, color);

    // Mark the allowed [minDist, maxDist] range measured from anchorA.
    Vec2 delta = anchorB - anchorA;
    float dist = delta.getLength();
    if (dist > 0.0f)
    {
        Vec2 dir = delta / dist;
        if (minDist > 0.0f)
        {
            _drawNode->drawPoint(anchorA + dir * minDist, JOINT_POINT_SIZE + 1.0f, color);
        }
        if (maxDist > minDist)
        {
            _drawNode->drawPoint(anchorA + dir * maxDist, JOINT_POINT_SIZE + 1.0f, color);
        }
    }

    _drawNode->drawPoint(anchorA, JOINT_POINT_SIZE, color);
    _drawNode->drawPoint(anchorB, JOINT_POINT_SIZE, color);
}

Color4F PhysicsDebugDraw::getShapeColor(PhysicsShape* shape) const
{
    if (shape == nullptr)
    {
        return _config.shapeColor;
    }

    Color4F color = getBodyColor(shape->getBody());

    // Sensors do not generate collision response, draw them translucent.
    if (shape->isSensor())
    {
        color.a *= 0.5f;
    }

    return color;
}

Color4F PhysicsDebugDraw::getBodyColor(PhysicsBody* body) const
{
    if (body == nullptr)
    {
        return _config.shapeColor;
    }

    // Resting bodies are drawn gray to highlight the sleeping state.
    if (body->isResting())
    {
        return Color4F(0.5f, 0.5f, 0.5f, _config.shapeColor.a);
    }

    Color4F color = _config.shapeColor;

    // Static and kinematic bodies are drawn slightly dimmed.
    if (!body->isDynamic())
    {
        color.r *= 0.6f;
        color.g *= 0.6f;
        color.b *= 0.6f;
    }

    return color;
}

